function supabaseErrorLogFields(error) {
    return {
        errorCode: error?.code ?? error?.cause?.code ?? null,
        errorMessage: String(error?.message || error || 'Unknown Supabase error'),
        errorDetails: error?.details ?? null,
        errorHint: error?.hint ?? null,
        errorStatus: error?.status ?? error?.cause?.status ?? null
    };
}

function logTurboAuthDiagnostic(message) {
    console.info(`[TURBO AUTH] ${message}`);
}

function safeDiagnosticMessage(value) {
    return String(value || 'Unknown error').replace(/[\r\n]+/g, ' ').trim();
}

async function supabaseResponseError(response) {
    try {
        const body = await response.clone().json();
        return {
            errorCode: body?.code || body?.error_code || `HTTP_${response.status}`,
            errorMessage: safeDiagnosticMessage(body?.message || body?.msg || response.statusText || `HTTP ${response.status}`)
        };
    } catch (error) {
        return {
            errorCode: `HTTP_${response.status}`,
            errorMessage: safeDiagnosticMessage(response.statusText || `HTTP ${response.status}`)
        };
    }
}

function sessionMatchesConfiguredProject(session) {
    try {
        const payload = session?.access_token?.split('.')?.[1];
        if (!payload) return 'unknown';
        const decoded = JSON.parse(atob(payload.replace(/-/g, '+').replace(/_/g, '/')));
        if (!decoded?.iss) return 'unknown';
        return new URL(decoded.iss).origin === new URL(SUPABASE_URL).origin ? 'true' : 'false';
    } catch (error) {
        return 'unknown';
    }
}
