function getTrustedPrivateRoomParentOrigins() {
    const configuredOrigins = document.querySelector('meta[name="turbocrib-private-room-parent-origins"]')?.content || '';
    const trustedOrigins = new Set();
    for (const configuredOrigin of configuredOrigins.split(',')) {
        const value = configuredOrigin.trim();
        if (!value) continue;
        try {
            const url = new URL(value);
            const secureOrigin = url.protocol === 'https:'
                || (url.protocol === 'http:' && ['localhost', '127.0.0.1', '[::1]'].includes(url.hostname));
            if (secureOrigin && url.pathname === '/' && !url.search && !url.hash && !url.username && !url.password) {
                trustedOrigins.add(url.origin);
            }
        } catch (error) {
            // Ignore malformed origin configuration; messages remain fail-closed.
        }
    }
    return trustedOrigins;
}

function normalizePrivateRoomDiagnosticCode(value) {
    const code = String(value || '').toUpperCase().replace(/[\s-]/g, '');
    return PRIVATE_ROOM_CODE_PATTERN.test(code) ? code : '';
}

function inspectPrivateRoomInviteLocation(search = '', hash = '') {
    const query = new URLSearchParams(String(search || ''));
    const hashParameters = new URLSearchParams(String(hash || '').replace(/^#/, ''));
    const queryHasCode = query.has('privateRoom');
    const hashHasCode = hashParameters.has('privateRoom');
    const rawCode = queryHasCode ? query.get('privateRoom') : hashParameters.get('privateRoom');
    return {
        parameterPresent: queryHasCode || hashHasCode,
        validCode: normalizePrivateRoomDiagnosticCode(rawCode)
    };
}

function findPrivateRoomDiagnosticCode(value, depth = 0, seen = new Set()) {
    if (!value || typeof value !== 'object' || depth > 3 || seen.has(value)) return '';
    seen.add(value);
    let entries;
    try {
        entries = Object.entries(value);
    } catch (error) {
        return '';
    }
    for (const [key, nestedValue] of entries) {
        if (/private.?room|invite.?code/i.test(key)) {
            const directCode = normalizePrivateRoomDiagnosticCode(nestedValue);
            if (directCode) return directCode;
            if (nestedValue && typeof nestedValue === 'object') {
                const nestedCode = findPrivateRoomDiagnosticCode(nestedValue, depth + 1, seen);
                if (nestedCode) return nestedCode;
            }
        }
        if (depth < 3 && /config|launch|query|params|invite/i.test(key)
            && nestedValue && typeof nestedValue === 'object') {
            const nestedCode = findPrivateRoomDiagnosticCode(nestedValue, depth + 1, seen);
            if (nestedCode) return nestedCode;
        }
    }
    return '';
}

function findPrivateRoomInviteDiagnosticConfigCode() {
    const configCandidates = [
        window.rosebudConfig,
        window.RosebudConfig,
        window.rosebud,
        window.gameConfig,
        window.config
    ];
    for (const candidate of configCandidates) {
        const code = findPrivateRoomDiagnosticCode(candidate);
        if (code) return code;
    }
    return '';
}

function logPrivateRoomInviteOuterDiagnostic() {
    let inspected = null;
    let source = 'unavailable';
    try {
        const outerLocation = window.top.location;
        inspected = inspectPrivateRoomInviteLocation(outerLocation.search, outerLocation.hash);
        source = window.top === window ? 'top-level URL' : 'readable outer URL';
    } catch (error) {
        try {
            if (document.referrer) {
                const referrer = new URL(document.referrer);
                inspected = inspectPrivateRoomInviteLocation(referrer.search, referrer.hash);
                source = 'referrer only';
            }
        } catch (referrerError) {
            inspected = null;
        }
    }
    const fields = inspected
        ? `privateRoom parameter present=${inspected.parameterPresent}; redacted room code present=${Boolean(inspected.validCode)}`
        : 'privateRoom parameter present=unknown; redacted room code present=unknown';
    console.info(`${PRIVATE_ROOM_INVITE_DIAGNOSTIC_PREFIX} OUTER/PUBLISHED URL: source=${source}; ${fields}`);
}

