        const scoreAfter = this.scoreTotal(update[`${side}Score`] || this.scoreFor(side), { ...state, ...update });
        update.countAnimation = this.countAnimationFor(update, side, 'hand', scoreBefore, scoreAfter, result.details);
        const sync = this.commit(update, 'coin');
