        this.cribRevealKey = revealKey;
        this.cribRevealAnimationStartedPhase = null;
        this.cribRevealLayout = null;
        this.cribRevealStartRect = null;
        this.cribRevealPendingClearKey = revealKey;
        this.cribRevealPendingDirect = false;
        const crib = this.gameState?.crib || [];
        const table = this.container?.querySelector('.game-table');
        const source = table?.querySelector(this.mobileMode ? '.mobile-crib-stack' : '.crib-stack');
        const sourceCards = new Set([...source?.querySelectorAll('[data-card-id]') || []].map((node) => String(node.dataset.cardId)));
        const matchingCards = crib.filter((card) => card?.id && sourceCards.has(String(card.id))).length;
        if (!this.hasRenderedGame || crib.filter(Boolean).length < 4 || matchingCards < 3 || !source) {
            this.cribRevealPendingDirect = true;
            return;
        }

        const sourceRect = source.getBoundingClientRect();
        const card = source.querySelector(this.mobileMode ? '.mobile-crib-card' : '.crib-card-flip');
        const cardRect = card?.getBoundingClientRect() || sourceRect;
        const tableRect = table.getBoundingClientRect();
        const scaleX = table.offsetWidth ? tableRect.width / table.offsetWidth : 1;
        const scaleY = table.offsetHeight ? tableRect.height / table.offsetHeight : 1;
