    promptUpCardFromChoices(choices, card) {
        return new Promise((resolve) => {
            const overlay = document.createElement('div');
            const mobileDialog = Boolean(this.mobileMode);
            let settled = false;
            overlay.className = `modal-shade value-selector-overlay card-declaration-modal joker-value-selector mobile-count-selector upcard-crib-selector${card?.type === 'joker' ? '' : ' ace-value-selector'}`;
            overlay.dataset.declarationLocation = 'upcard';
            overlay.dataset.declarationCardId = String(card?.id || '');
            overlay.dataset.declarationContext = 'crib';
            const closeButtonMarkup = mobileDialog
                ? '<button type="button" class="joker-close-btn" aria-label="Cancel crib value selection" title="Return to game">×</button>'
                : '';
            const cancelButtonMarkup = mobileDialog
                ? ''
                : '<div class="action-row"><button class="action-btn secondary cancel" type="button">CANCEL</button></div>';
            const finish = (value) => {
                if (settled) return;
                settled = true;
                overlay.remove();
                this.syncDesktopActionPrompt();
                resolve(value);
            };
            const closeDialog = () => finish(null);
            overlay.innerHTML = `<div class="choice-modal" role="dialog" aria-modal="true">${closeButtonMarkup}<h2>Crib Upcard</h2><p>Choose one of the two declarations locked from the main hands.</p><div class="choice-grid upcard-choice-grid${card?.type === 'joker' ? '' : ' ace-value-grid'}"></div>${cancelButtonMarkup}</div>`;
            const grid = overlay.querySelector('.upcard-choice-grid');
            const lockedChoiceEntries = this.cribUpCardChoiceEntries(card);
            choices.forEach((choice) => {
                const button = document.createElement('button');
                const rank = card.type === 'joker' ? (choice.rank || 'A') : 'A';
                const value = card.type === 'joker' ? this.jokerDisplayValue(choice) : choice.value;
                const accessibleValue = card.type === 'joker'
                    ? this.jokerValueForRank(rank, choice.value)
                    : this.validAceValue(choice.value);
                const isAceValueChoice = rank === 'A';
                const displayValue = value;
                const declarationLabel = card.type === 'joker'
                    ? `Use the Joker upcard as ${rank === 'A' ? `Ace with value ${accessibleValue}` : `${rank} with value ${accessibleValue}`}`
                    : `Use the upcard as A${value}`;
                const choiceKey = this.computerUpCardChoiceKey(choice);
                const matchingSides = lockedChoiceEntries
                    .filter((entry) => this.computerUpCardChoiceKey(entry.choice) === choiceKey)
                    .map((entry) => entry.side);
                const sourceSide = matchingSides.length > 1
                    ? 'both'
                    : (matchingSides[0] || null);
                const sourceLabel = sourceSide === 'both'
                    ? 'BOTH HANDS'
                    : sourceSide === this.playerSide ? 'YOUR HAND' : 'OPPONENT HAND';
                const accessibleSource = sourceSide === 'both'
                    ? 'from both hands'
                    : sourceSide === this.playerSide ? 'from your hand' : 'from opponent hand';
                button.type = 'button';
                button.className = `selector-card-choice card-declaration-choice${isAceValueChoice ? ' selector-ace-choice' : ' selector-joker-choice'}`;
                button.setAttribute('aria-label', `${declarationLabel}, ${accessibleSource}`);
                button.innerHTML = this.selectorCardMarkup(rank, displayValue, isAceValueChoice ? 'ace-value' : 'joker');
                const source = document.createElement('span');
                source.className = 'crib-upcard-choice-source';
                source.textContent = sourceLabel;
                button.appendChild(source);
                button.onclick = () => finish(choice);
                grid.appendChild(button);
            });
            const cancelButton = overlay.querySelector('.cancel');
            if (cancelButton) cancelButton.onclick = closeDialog;
            if (mobileDialog) overlay.querySelector('.joker-close-btn').onclick = closeDialog;
            overlay.addEventListener('click', (event) => { if (event.target === overlay) closeDialog(); });
            this.appendModalOverlay(overlay);
            this.syncDesktopActionPrompt();
            this.placeValueSelector(overlay);
        });
    }

